import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import InputField from '../../../components/ui/InputField/InputField';
import Modal from '../../../components/ui/Modal/Modal';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';
import styles from './ListUsersPage.module.css'; // Importa o CSS para os modais

const ListUsersPage = () => {
  const [users, setUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [isViewModalOpen, setViewModalOpen] = useState(false);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);

  const headers = [
    { key: 'id', label: 'ID' },
    { key: 'name', label: 'Nome' },
    { key: 'email', label: 'Email' },
    { key: 'seal_balance', label: 'Selos' }
  ];

  const fetchUsers = async () => {
    try {
      const response = await api.get('/users');
      setUsers(response.data);
    } catch (error) {
      console.error("Erro ao buscar utilizadores:", error);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleView = (user) => {
    setSelectedUser(user);
    setViewModalOpen(true);
  };

  const handleDelete = (user) => {
    setSelectedUser(user);
    setDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    try {
      await api.delete(`/users/${selectedUser.id}`);
      setDeleteModalOpen(false);
      fetchUsers(); // Atualiza a lista após a exclusão
    } catch (error) {
      console.error("Erro ao excluir utilizador:", error);
      alert("Ocorreu um erro ao excluir o utilizador.");
    }
  };

  const filteredUsers = users.filter(user =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <ContentWrapper title="Listar Usuários">
      <div style={{ marginBottom: '1.5rem', maxWidth: '400px' }}>
        <InputField
          label="Pesquisar por nome ou email"
          name="search"
          placeholder="Digite para pesquisar..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>
      <Table 
        headers={headers} 
        data={filteredUsers} 
        onView={handleView}
        onDelete={handleDelete}
      />

      {/* Modal de Visualização */}
      <Modal 
        isOpen={isViewModalOpen} 
        onClose={() => setViewModalOpen(false)} 
        title="Detalhes do Usuário"
      >
        {selectedUser && (
          <div className={styles.modalContent}>
            <p><strong>ID:</strong> {selectedUser.id}</p>
            <p><strong>Nome:</strong> {selectedUser.name}</p>
            <p><strong>Email:</strong> {selectedUser.email}</p>
            <p><strong>Saldo de Selos:</strong> {selectedUser.seal_balance}</p>
            <div className={styles.modalActions}>
              <Button onClick={() => alert('Navegar para editar perfil do usuário')}>Editar Perfil</Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Modal de Exclusão */}
      <Modal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setDeleteModalOpen(false)} 
        title="Confirmar Exclusão"
      >
        {selectedUser && (
          <div className={styles.modalContent}>
            <p>Tem a certeza de que deseja excluir o usuário <strong>{selectedUser.name}</strong>?</p>
            <p>Esta ação não pode ser desfeita.</p>
            <div className={styles.modalActions}>
              <Button variant="secondary" onClick={() => setDeleteModalOpen(false)}>Cancelar</Button>
              <Button variant="danger" onClick={confirmDelete}>Excluir</Button>
            </div>
          </div>
        )}
      </Modal>
    </ContentWrapper>
  );
};

export default ListUsersPage;
